```sql
CREATE OR REPLACE TEMP VIEW s2 AS
SELECT l.*, coalesce(nullif(e.lei,''),e.entity_id) k, e.country, e.source_system FROM (SELECT *, row_number() OVER (PARTITION BY rated_id, rating_type, coalesce(ccy_basis,'') ORDER BY date DESC, action_id DESC) rn FROM rating_actions WHERE date<='2026-10-01') l JOIN entities e ON e.entity_id=l.rated_id WHERE rn=1;
SELECT 'Q9' q, count(DISTINCT k)::varchar v FROM s2 WHERE rating_type='LTIDR' AND rating<>'WD'
UNION ALL SELECT 'Q40', count(DISTINCT k)::varchar FROM s2 WHERE rating_type='LTIDR' AND rating<>'WD' AND country='GB'
UNION ALL SELECT 'Q48', count(DISTINCT rated_id)::varchar FROM s2 WHERE rating_type='INST' AND action<>'EX' AND rating<>'WD'
UNION ALL SELECT 'Q25', count(DISTINCT rated_id)::varchar FROM s2 WHERE rating_type='INST' AND action<>'EX' AND rating IN ('AA','AA-','A+','A','A-','BBB+','BBB','BBB-');
SELECT 'RWN' t, rated_id, k, ccy_basis, rating, date FROM s2 WHERE rating_type='LTIDR' AND watch='RWN' UNION ALL SELECT 'NEG', rated_id, k, ccy_basis, rating, date FROM s2 WHERE rating_type='LTIDR' AND outlook='NEG' AND rating<>'WD' ORDER BY 1,3;
SELECT a.rated_id, a.date, a.k, (SELECT string_agg(b.rated_id||':'||b.rating||':'||b.action, ',') FROM s2 b WHERE b.k=a.k AND b.rating_type='LTIDR' AND b.rated_id<>a.rated_id) other FROM s2 a WHERE a.rating_type='LTIDR' AND a.rating='WD' ORDER BY 1;
```

